# Let me search the entire context for any lab reference info
import os

all_text = ""
for root, dirs, files in os.walk('.'):
    for file in files:
        try:
            with open(os.path.join(root, file), 'r') as f:
                content = f.read()
                if len(content) < 50000:  # Skip very large files
                    all_text += content + "\n"
        except:
            pass

# Search for lab ranges
print("Searching for lab reference ranges...")

# Patterns to look for
patterns = [
    r'WBC\s*(?:is\s+)?(?:\d+\.?\d*)\s*(?:to|-)\s*(?:\d+\.?\d*)',
    r'FG\s*(?:is\s+)?(?:\d+\.?\d*)\s*(?:to|-)\s*(?:\d+\.?\d*)',
    r'fibrinogen\s*(?:is\s+)?(?:\d+\.?\d*)\s*(?:to|-)\s*(?:\d+\.?\d*)',
    r'normal\s+range\s+(?:for\s+)?(?:\w+)?\s*(?:is\s+)?[\d.]+',
    r'beyond\s+the\s+normal\s+range',
]

import re
for pattern in patterns:
    matches = re.findall(pattern, all_text, re.IGNORECASE)
    if matches:
        print(f'Pattern {pattern}: {matches}')

